import { getSettingsPageMetadata } from "@/modules/settings/lib/metadata";
import { TagsPage } from "@/modules/workspaces/settings/tags/page";

export const generateMetadata = () => getSettingsPageMetadata("common.tags");

export default TagsPage;

/**
 * GET /api/v3/tags — list a workspace's tags with their response counts.
 *
 * Session-only, deliberately. These endpoints replace `authenticatedActionClient` server actions that
 * only ever ran for a signed-in user, so accepting `x-api-key` here would widen the surface rather than
 * migrate it.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { listV3Tags } from "./lib/operations";
import { ZV3TagListQuery } from "./lib/schemas";

export const GET = withV3ApiWrapper({
  auth: "session",
  schemas: { query: ZV3TagListQuery },
  handler: async ({ authentication, parsedInput, requestId, instance }) =>
    listV3Tags({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      requestId,
      instance,
    }),
});

/**
 * PATCH  /api/v3/tags/{tagId} — rename a tag.
 * DELETE /api/v3/tags/{tagId} — delete a tag and its response links.
 *
 * The workspace is resolved from the tag, never from the request, so the caller cannot supply the scope
 * it is authorized against. Session-only, matching the actions these replace.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { deleteV3Tag, renameV3Tag } from "../lib/operations";
import { ZV3RenameTagBody, ZV3TagIdParams } from "../lib/schemas";

export const PATCH = withV3ApiWrapper({
  auth: "session",
  action: "updated",
  targetType: "tag",
  schemas: { params: ZV3TagIdParams, body: ZV3RenameTagBody },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    renameV3Tag({
      authentication,
      tagId: parsedInput.params.tagId,
      name: parsedInput.body.name,
      auditLog,
      requestId,
      instance,
    }),
});

export const DELETE = withV3ApiWrapper({
  auth: "session",
  action: "deleted",
  targetType: "tag",
  schemas: { params: ZV3TagIdParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    deleteV3Tag({
      authentication,
      tagId: parsedInput.params.tagId,
      auditLog,
      requestId,
      instance,
    }),
});

import "server-only";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import {
  problemBadRequest,
  problemForbidden,
  problemInternalError,
  problemUnprocessableContent,
  successResponse,
} from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { resolveV3ResponsesActorContext } from "@/app/api/v3/responses/lib/visibility";
import { buildVisibleSurveyWhere } from "@/lib/survey/visibility/predicate";
import { getTag, getTagsByWorkspaceId } from "@/lib/tag/service";
import { getTagsOnResponsesCount } from "@/lib/tagOnResponse/service";
import { deleteTag, mergeTags, updateTagName } from "@/modules/workspaces/settings/lib/tag";
import { serializeV3Tag } from "../serializers";

type TBaseParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
};

/**
 * Every mutation resolves the workspace from the tag itself rather than trusting a client-supplied
 * `workspaceId`. That keeps the scope unforgeable: a caller cannot pair someone else's tag id with a
 * workspace they happen to have access to. It also reproduces what the server actions did via
 * `getWorkspaceIdFromTagId`, so the authorization matrix is unchanged — organization owners and managers,
 * or a workspace team member with `readWrite`.
 *
 * An unknown tag answers 403, not 404, matching `/api/v3/surveys/{surveyId}` and
 * `/api/v3/workflows/{workflowId}`: a 404 here would let any signed-in user probe tag ids across the
 * whole instance and learn which exist.
 */
async function authorizeTagMutation(
  tagId: string,
  { authentication, requestId, instance }: TBaseParams
): Promise<Response | { tag: NonNullable<Awaited<ReturnType<typeof getTag>>>; organizationId: string }> {
  const tag = await getTag(tagId);
  if (!tag) {
    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
  }

  const access = await requireV3WorkspaceAccess(
    authentication,
    tag.workspaceId,
    "readWrite",
    requestId,
    instance
  );
  if (access instanceof Response) return access;

  return { tag, organizationId: access.organizationId };
}

/** A tag's count only covers responses the caller may read (ENG-3282). */
const getVisibleTagCounts = async (
  authentication: TV3Authentication,
  workspaceId: string,
  organizationId: string
) =>
  getTagsOnResponsesCount(
    workspaceId,
    buildVisibleSurveyWhere(await resolveV3ResponsesActorContext(authentication, organizationId))
  );

export async function listV3Tags(params: TBaseParams & { workspaceId: string }): Promise<Response> {
  const { authentication, workspaceId, requestId, instance } = params;

  const access = await requireV3WorkspaceAccess(authentication, workspaceId, "read", requestId, instance);
  if (access instanceof Response) return access;

  const [tags, counts] = await Promise.all([
    getTagsByWorkspaceId(access.workspaceId),
    getVisibleTagCounts(authentication, access.workspaceId, access.organizationId),
  ]);

  const countByTagId = new Map(counts.map((entry) => [entry.tagId, entry.count]));

  return successResponse(
    tags.map((tag) => serializeV3Tag(tag, countByTagId.get(tag.id) ?? 0)),
    { requestId }
  );
}

export async function renameV3Tag(
  params: TBaseParams & { tagId: string; name: string; auditLog?: TV3AuditLog }
): Promise<Response> {
  const { tagId, name, auditLog, requestId, instance } = params;

  const authorized = await authorizeTagMutation(tagId, params);
  if (authorized instanceof Response) return authorized;

  if (auditLog) {
    auditLog.organizationId = authorized.organizationId;
    auditLog.targetId = tagId;
    auditLog.oldObject = authorized.tag;
  }

  const result = await updateTagName(tagId, name);
  if (!result.ok) {
    // A duplicate name is the caller's problem, not a server fault: the component surfaces it inline.
    return problemUnprocessableContent(requestId, "Unable to update tag", {
      instance,
      invalid_params: [{ name: "name", reason: result.error.code ?? "invalid" }],
    });
  }

  if (auditLog) auditLog.newObject = result.data;

  // `count` is part of the documented `TagResource`, so a rename cannot answer 0 for a tag that is in
  // use — that would be false data, not merely an omission. A rename does not change the count, so this
  // reads the current one. `getTagsOnResponsesCount` is workspace-wide and `reactCache`d, the same call
  // the list route makes.
  const counts = await getVisibleTagCounts(
    params.authentication,
    authorized.tag.workspaceId,
    authorized.organizationId
  );
  const count = counts.find((entry) => entry.tagId === tagId)?.count ?? 0;

  return successResponse(serializeV3Tag(result.data, count), { requestId });
}

export async function deleteV3Tag(
  params: TBaseParams & { tagId: string; auditLog?: TV3AuditLog }
): Promise<Response> {
  const { tagId, auditLog, requestId, instance } = params;

  const authorized = await authorizeTagMutation(tagId, params);
  if (authorized instanceof Response) return authorized;

  if (auditLog) {
    auditLog.organizationId = authorized.organizationId;
    auditLog.targetId = tagId;
  }

  const result = await deleteTag(tagId);
  if (!result.ok) {
    return problemInternalError(requestId, "Unable to delete tag", instance);
  }

  if (auditLog) auditLog.oldObject = result.data;

  return successResponse({ id: tagId }, { requestId });
}

export async function mergeV3Tags(
  params: TBaseParams & { tagId: string; newTagId: string; auditLog?: TV3AuditLog }
): Promise<Response> {
  const { tagId, newTagId, auditLog, requestId, instance } = params;

  const authorized = await authorizeTagMutation(tagId, params);
  if (authorized instanceof Response) return authorized;

  // Merging a tag into itself is a malformed request, not a server fault. `mergeTags` does reject it
  // with `MERGE_SAME_TAG`, but every service failure below maps to 500, so without this check the
  // caller would get a 500 for their own bad input. 400 is what the OpenAPI document already promises.
  if (tagId === newTagId) {
    return problemBadRequest(requestId, "A tag cannot be merged into itself", {
      instance,
      invalid_params: [{ name: "newTagId", reason: "must differ from the tag being merged away" }],
    });
  }

  // Both tags must live in the same workspace, or merging would move responses across a tenant
  // boundary. The server action checked this too; it is the one rule that needs the second tag loaded.
  const target = await getTag(newTagId);
  if (!target) {
    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
  }
  if (target.workspaceId !== authorized.tag.workspaceId) {
    return problemForbidden(requestId, "Tags must be in the same workspace", instance);
  }

  if (auditLog) {
    auditLog.organizationId = authorized.organizationId;
    auditLog.targetId = `${tagId}-${newTagId}`;
    auditLog.oldObject = authorized.tag;
  }

  const result = await mergeTags(tagId, newTagId);
  if (!result.ok) {
    return problemInternalError(requestId, "Unable to merge tags", instance);
  }

  if (auditLog) auditLog.newObject = result.data;

  return successResponse({ id: newTagId }, { requestId });
}

import { z } from "zod";

export const ZV3TagIdParams = z.object({ tagId: z.cuid2() }).strict();

export const ZV3TagListQuery = z.object({ workspaceId: z.cuid2() }).strict();

/**
 * The old `updateTagNameAction` accepted a bare `z.string()` and the component trimmed before calling.
 * Trimming and rejecting empty here instead means a blank rename is a 422 rather than a tag silently
 * named "".
 */
export const ZV3RenameTagBody = z.object({ name: z.string().trim().min(1).max(255) }).strict();

export const ZV3MergeTagBody = z.object({ newTagId: z.cuid2() }).strict();

export type TV3TagIdParams = z.infer<typeof ZV3TagIdParams>;
export type TV3TagListQuery = z.infer<typeof ZV3TagListQuery>;

import type { TTag } from "@formbricks/types/tags";

export type TV3Tag = {
  id: string;
  name: string;
  workspaceId: string;
  createdAt: string;
  updatedAt: string;
  /** Responses currently carrying this tag. Zero when the tag has never been applied. */
  count: number;
};

export const serializeV3Tag = (tag: TTag, count: number): TV3Tag => ({
  id: tag.id,
  name: tag.name,
  workspaceId: tag.workspaceId,
  createdAt: tag.createdAt.toISOString(),
  updatedAt: tag.updatedAt.toISOString(),
  count,
});

"use client";

import { useQuery } from "@tanstack/react-query";
import { getTags } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/** A workspace's tags with their response counts — the table's only data source. */
export const useTags = (workspaceId: string) =>
  useQuery({
    queryKey: tagKeys.list(workspaceId),
    queryFn: ({ signal }) => getTags({ workspaceId, signal }),
  });

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { deleteTag } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/** Delete a tag, then invalidate the list — replacing a `router.refresh()` full-page revalidation. */
export const useDeleteTag = (workspaceId: string) => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (variables: { tagId: string }) => deleteTag(variables),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: tagKeys.list(workspaceId) }),
  });
};

import { SettingsCard } from "@/app/(app)/workspaces/[workspaceId]/settings/components/SettingsCard";
import { getTranslate } from "@/lingodotdev/server";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { getWorkspaceAuth } from "@/modules/workspaces/lib/utils";
import { EditTagsWrapper } from "./components/edit-tags-wrapper";

export const TagsPage = async (props: { params: Promise<{ workspaceId: string }> }) => {
  const params = await props.params;
  const t = await getTranslate();

  // The tags themselves are fetched client-side through `/api/v3/tags`, so this page only resolves the
  // permission that decides whether the actions column renders.
  const { isReadOnly } = await getWorkspaceAuth(params.workspaceId);

  return (
    <PageContentWrapper>
      <PageHeader pageTitle={t("common.tags")} />
      <SettingsCard
        title={t("workspace.tags.manage_tags")}
        description={t("workspace.tags.manage_tags_description")}
        bodyVariant="flush">
        <EditTagsWrapper workspaceId={params.workspaceId} isReadOnly={isReadOnly} />
      </SettingsCard>
    </PageContentWrapper>
  );
};

import type { TV3Tag } from "@/app/api/v3/tags/serializers";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client fetchers for the tags v3 routes. Reads forward the TanStack `signal`; every call throws a parsed
 * `V3ApiError` on a non-2xx response, so the hooks can surface the server's own message.
 */

const BASE_PATH = "/api/v3/tags";

async function request<T>(url: string, init: RequestInit): Promise<T> {
  const response = await fetch(url, { cache: "no-store", ...init });
  if (!response.ok) {
    throw await parseV3ApiError(response);
  }
  return ((await response.json()) as { data: T }).data;
}

export async function getTags(params: { workspaceId: string; signal?: AbortSignal }): Promise<TV3Tag[]> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<TV3Tag[]>(`${BASE_PATH}?${query.toString()}`, {
    method: "GET",
    signal: params.signal,
  });
}

export async function renameTag(params: { tagId: string; name: string }): Promise<TV3Tag> {
  return request<TV3Tag>(`${BASE_PATH}/${params.tagId}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: params.name }),
  });
}

export async function deleteTag(params: { tagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}`, { method: "DELETE" });
}

export async function mergeTags(params: { tagId: string; newTagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}/merge`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ newTagId: params.newTagId }),
  });
}

/** Typed query-key factory. Never inline string keys — the mutation hooks invalidate these exact tuples. */
const tagCacheKeyBase = ["workspace-tags"] as const;

export const tagKeys = {
  all: tagCacheKeyBase,
  list: (workspaceId: string) => [...tagCacheKeyBase, "list", workspaceId] as const,
};

"use client";

import type { TFunction } from "i18next";
import { useTranslation } from "react-i18next";
import type { TV3Tag } from "@/app/api/v3/tags/serializers";
import { getV3ApiErrorMessage } from "@/modules/api/lib/v3-client";
import { Button } from "@/modules/ui/components/button";
import { SettingsTable, type TSettingsTableColumn } from "@/modules/ui/components/settings-table";
import { TagNameInput } from "@/modules/workspaces/settings/tags/components/tag-name-input";
import { TagRowActions } from "@/modules/workspaces/settings/tags/components/tag-row-actions";
import { useTags } from "@/modules/workspaces/settings/tags/hooks/use-tags";

interface EditTagsWrapperProps {
  workspaceId: string;
  isReadOnly: boolean;
}

/**
 * Exported so `loading.tsx` builds its skeleton from the same array. That skeleton used to hand-roll the
 * header and had already drifted: it rendered the actions column unconditionally while the real table
 * gates it on `!isReadOnly`, so a read-only viewer saw a three-column skeleton resolve into a two-column
 * table.
 *
 * Defined at module level rather than inside the component: an inline `cell` that returns JSX reads as a
 * nested component definition to Sonar (typescript:S6478).
 */
export const getTagColumns = ({
  t,
  workspaceId,
  tags,
  isReadOnly,
}: Readonly<{
  t: TFunction;
  workspaceId: string;
  tags: TV3Tag[];
  isReadOnly: boolean;
}>): TSettingsTableColumn<TV3Tag>[] => {
  const columns: TSettingsTableColumn<TV3Tag>[] = [
    {
      id: "tag",
      header: t("workspace.tags.tag"),
      headerClassName: "w-[50%]",
      skeletonWidth: "w-full",
      cell: (tag) => (
        <TagNameInput tagId={tag.id} tagName={tag.name} workspaceId={workspaceId} isReadOnly={isReadOnly} />
      ),
    },
    {
      id: "count",
      header: t("workspace.tags.count"),
      headerClassName: "w-[15%]",
      align: "center",
      cellClassName: "whitespace-nowrap text-slate-900",
      skeletonWidth: "w-8",
      cell: (tag) => tag.count,
    },
  ];

  if (!isReadOnly) {
    columns.push({
      id: "actions",
      header: t("common.actions"),
      headerClassName: "w-[35%]",
      align: "center",
      skeletonWidth: "w-40",
      cell: (tag) => (
        <TagRowActions
          tagId={tag.id}
          tagName={tag.name}
          workspaceId={workspaceId}
          mergeableTags={tags
            .filter((candidate) => candidate.id !== tag.id)
            .map((candidate) => ({ label: candidate.name, value: candidate.id }))}
        />
      ),
    });
  }

  return columns;
};

export const EditTagsWrapper = ({ workspaceId, isReadOnly }: Readonly<EditTagsWrapperProps>) => {
  const { t } = useTranslation();
  // The tag list lives in the query cache, so a rename, merge or delete invalidates it instead of
  // calling `router.refresh()` to revalidate the whole route.
  const { data: tags = [], isPending, isError, error, refetch } = useTags(workspaceId);

  // A failed fetch must not fall through to the table: `data` defaults to `[]`, so the empty state would
  // claim the workspace has no tags when the request merely failed. Same shape as `survey-list.tsx` and
  // `workflow-runs-table.tsx`.
  if (isError && tags.length === 0) {
    return (
      <div className="flex w-full flex-col items-center justify-center gap-4 py-16 text-slate-600">
        <p>{getV3ApiErrorMessage(error, t("common.something_went_wrong_please_try_again"))}</p>
        <Button variant="secondary" size="sm" onClick={() => refetch()}>
          {t("common.try_again")}
        </Button>
      </div>
    );
  }

  return (
    <SettingsTable
      columns={getTagColumns({ t, workspaceId, tags, isReadOnly })}
      rows={tags}
      getRowId={(tag) => tag.id}
      // Keyed by the id the API returned, so `settings-tags.spec.ts` can address a row without matching
      // on the name — the one thing a rename changes.
      getRowProps={(tag) => ({ "data-testid": `tag-row-${tag.id}` })}
      isLoading={isPending}
      emptyMessage={t("workspace.tags.no_tag_found")}
      aria-label={t("common.tags")}
    />
  );
};

"use client";

import { useState } from "react";
import { toast } from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { getV3ApiErrorMessage } from "@/modules/api/lib/v3-client";
import { Button } from "@/modules/ui/components/button";
import { DeleteDialog } from "@/modules/ui/components/delete-dialog";
import { LoadingSpinner } from "@/modules/ui/components/loading-spinner";
import { MergeTagsCombobox } from "@/modules/workspaces/settings/tags/components/merge-tags-combobox";
import { useDeleteTag } from "@/modules/workspaces/settings/tags/hooks/use-delete-tag";
import { useMergeTags } from "@/modules/workspaces/settings/tags/hooks/use-merge-tags";

interface TagRowActionsProps {
  tagId: string;
  tagName: string;
  workspaceId: string;
  mergeableTags: { label: string; value: string }[];
}

/**
 * The actions column's cell — merge and delete. Split out of the old `SingleTag` row along with
 * `TagNameInput`; it owns the merge-in-flight and delete-dialog state that used to sit on the whole row.
 */
export const TagRowActions = ({
  tagId,
  tagName,
  workspaceId,
  mergeableTags,
}: Readonly<TagRowActionsProps>) => {
  const { t } = useTranslation();
  const [openDeleteTagDialog, setOpenDeleteTagDialog] = useState(false);
  const deleteTag = useDeleteTag(workspaceId);
  const mergeTags = useMergeTags(workspaceId);

  const confirmDeleteTag = async () => {
    try {
      await deleteTag.mutateAsync({ tagId });
      toast.success(t("workspace.tags.tag_deleted"));
    } catch (error) {
      toast.error(getV3ApiErrorMessage(error, t("common.something_went_wrong_please_try_again")));
    }
  };

  const handleMergeTags = async (newTagId: string) => {
    try {
      await mergeTags.mutateAsync({ tagId, newTagId });
      toast.success(t("workspace.tags.tags_merged"));
    } catch (error) {
      toast.error(getV3ApiErrorMessage(error, t("common.something_went_wrong_please_try_again")));
    }
  };

  return (
    // The flex sits here rather than on `cellClassName`, which would land on the `<td>` and stop it being
    // a table cell.
    <div className="flex items-center justify-center gap-2">
      {mergeTags.isPending ? (
        <div className="w-24">
          <LoadingSpinner />
        </div>
      ) : (
        <MergeTagsCombobox tags={mergeableTags} onSelect={handleMergeTags} />
      )}
      <Button
        variant="destructive"
        size="sm"
        loading={deleteTag.isPending}
        className="font-medium text-slate-50 focus:border-transparent focus:ring-0 focus:shadow-transparent focus:ring-transparent focus:outline-transparent"
        onClick={() => setOpenDeleteTagDialog(true)}>
        {t("common.delete")}
      </Button>
      <DeleteDialog
        open={openDeleteTagDialog}
        setOpen={setOpenDeleteTagDialog}
        deleteWhat={tagName}
        text={t("workspace.tags.delete_tag_confirmation")}
        onDelete={confirmDeleteTag}
        isDeleting={deleteTag.isPending}
      />
    </div>
  );
};

import { z } from "zod";

export const ZTag = z.object({
  id: z.cuid2(),
  createdAt: z.date(),
  updatedAt: z.date(),
  name: z.string(),
  workspaceId: z.cuid2(),
});
export type TTag = z.infer<typeof ZTag>;

export const ZTagsCount = z.array(
  z.object({
    tagId: z.cuid2(),
    count: z.number(),
  })
);
export type TTagsCount = z.infer<typeof ZTagsCount>;

export const ZTagsOnResponses = z.object({
  responseId: z.string(),
  tagId: z.string(),
});
export type TTagsOnResponses = z.infer<typeof ZTagsOnResponses>;

import type { ReactNode } from "react";

export type TSettingsTableAlign = "left" | "center" | "right";
export type TSettingsTableBreakpoint = "sm" | "md" | "lg";

/**
 * `none` — the table draws no frame, because a `<SettingsCard bodyVariant="flush">` already frames it.
 * `card` — the table draws its own frame, for use outside a settings card.
 */
export type TSettingsTableFrame = "none" | "card";

export type TSettingsTableColumn<TRow> = {
  /** Stable identifier, used as the React key for this column's header and every one of its cells. */
  id: string;
  /** Already-translated header label. `null` renders an empty header cell — pair it with `srLabel`. */
  header: ReactNode;
  cell: (row: TRow, index: number) => ReactNode;
  /**
   * Sets `text-align` on the header cell and every body cell in this column. Defaults to `left`.
   *
   * It moves **inline-level** content, which covers text, badges and `Button`/`Link` (both `inline-flex`).
   * It cannot move a block-level child, so a cell whose content is a wrapper `<div>` — or the skeleton's
   * placeholder bar — is unaffected by it. Declaring it alongside a flex wrapper is therefore inert; pick
   * one and let it be the only alignment source for the column.
   */
  align?: TSettingsTableAlign;
  /** Hides the column below this breakpoint. Applied to the header and body cells together. */
  hideBelow?: TSettingsTableBreakpoint;
  /**
   * Extra classes merged onto the `<th>`.
   *
   * This is where a column's **width** belongs (`w-[22%]`, `w-16`), because the header cell is what
   * sizes the whole column — putting a width on `cellClassName` only affects that one cell. Widths are
   * suggestions rather than commands: the table is `table-auto`, so a long value can still borrow space
   * from a short one, and when a `hideBelow` column drops out the remaining widths rescale.
   */
  headerClassName?: string;
  /**
   * Extra classes merged onto every `<td>` in this column, e.g. `font-medium text-slate-900`.
   *
   * **Do not change the cell's `display` here** — no `flex`, `grid` or `block`. These classes land on the
   * `<td>` itself, so overriding `display` stops it being a table-cell: the shared `align-middle` becomes
   * a no-op (`vertical-align` applies only to inline-level and table-cell boxes) and the browser wraps the
   * cell in an anonymous table-cell that defaults to baseline, so the content sits high in the row. To lay
   * cell content out, put the flex on a wrapper element **inside** `cell` instead. (`hideBelow` exists for
   * the same reason — it uses `table-cell`, not `block`.)
   */
