  // `workflow-runs-table.tsx`.
  if (isError && tags.length === 0) {
    return (
      <div className="flex w-full flex-col items-center justify-center gap-4 py-16 text-slate-600">
        <p>{getV3ApiErrorMessage(error, t("common.something_went_wrong_please_try_again"))}</p>
        <Button variant="secondary" size="sm" onClick={() => refetch()}>
          {t("common.try_again")}
        </Button>
      </div>
    );
  }

  return (
    <>
      {!isReadOnly && (
        <div className="flex justify-end pb-4">
          <Button
            variant="destructive"
            size="sm"
            loading={deleteUnusedMutation.isPending}
            onClick={() => setOpenDeleteUnusedDialog(true)}>
            {t("workspace.tags.delete_unused_tags")}
          </Button>
        </div>
      )}
      <SettingsTable
        columns={getTagColumns({ t, workspaceId, tags, isReadOnly })}
        rows={tags}
        getRowId={(tag) => tag.id}
        // Keyed by the id the API returned, so `settings-tags.spec.ts` can address a row without matching
        // on the name — the one thing a rename changes.
        getRowProps={(tag) => ({ "data-testid": `tag-row-${tag.id}` })}
        isLoading={isPending}
        emptyMessage={t("workspace.tags.no_tag_found")}
        aria-label={t("common.tags")}
      />
      <DeleteDialog
        open={openDeleteUnusedDialog}
        setOpen={setOpenDeleteUnusedDialog}
        deleteWhat={t("workspace.tags.delete_unused_tags")}
        text={t("workspace.tags.delete_unused_tags_confirmation")}
        onDelete={() => deleteUnusedMutation.mutate()}
        isDeleting={deleteUnusedMutation.isPending}
      />
    </>
  );
};

export const timeSinceDate = (date: Date, locale: string = DEFAULT_LOCALE) => {
  return formatDistance(date, new Date(), {
    addSuffix: true,
    locale: getLocaleForTimeSince(locale),
  });
};

